import { LitElement, html, css, nothing } from 'lit';
import { html as staticHtml, unsafeStatic } from 'lit/static-html.js';
/* eslint-disable-next-line @typescript-eslint/no-unused-vars */
import { property, query, state } from 'lit/decorators.js';
import { ScopedElementsMixin } from '@open-wc/scoped-elements/lit-element.js';

import { newEditEventV2 } from '@openscd/oscd-api/utils.js';
import { getReference, identity } from '@openscd/scl-lib';

import type { EditV2 } from '@openscd/oscd-api';
import { Button } from '@material/mwc-button';
import { Dialog } from '@material/mwc-dialog';
import { Fab } from '@material/mwc-fab';
import { Icon } from '@material/mwc-icon';
import { IconButton } from '@material/mwc-icon-button';
import { IconButtonToggle } from '@material/mwc-icon-button-toggle';
import { List, SingleSelectedEvent } from '@material/mwc-list';
import { ListItem } from '@material/mwc-list/mwc-list-item.js';
import { Menu } from '@material/mwc-menu';
import { SldEditor } from './sld-editor.js';

import { bayIcon, equipmentIcon, ptrIcon, voltageLevelIcon } from './icons.js';
import {
  eqTypes,
  getSLDAttributes,
  iedReferences,
  isBusBar,
  makeBusBar,
  resolveIed,
  setSLDAttributes,
  sldNs,
  xmlnsNs,
} from './util.js';
import { convertSldLayout, hasOldNamespace } from './converter.js';

const aboutContent = await fetch(new URL('about.html', import.meta.url)).then(
  res => res.text()
);

export default class OscdEditorSld extends ScopedElementsMixin(LitElement) {
  static scopedElements = {
    'mwc-button': Button,
    'mwc-dialog': Dialog,
    'mwc-fab': Fab,
    'mwc-icon': Icon,
    'mwc-icon-button': IconButton,
    'mwc-icon-button-toggle': IconButtonToggle,
    'mwc-list': List,
    'mwc-list-item': ListItem,
    'mwc-menu': Menu,
    'sld-editor': SldEditor,
  };

  @property()
  doc!: XMLDocument;

  @property()
  docVersion: number = -1;

  @state()
  gridSize = 32;

  @state()
  nsp = 'eosld';

  @state()
  templateElements: Record<string, Element> = {};

  @state()
  inAction: boolean = false;

  @state()
  get showLabels(): boolean {
    if (this.labelToggle) return this.labelToggle.on;
    return true;
  }

  @state()
  get showIeds(): boolean {
    if (this.iedToggle) return this.iedToggle.on;
    return true;
  }

  @query('#labels') labelToggle?: IconButtonToggle;

  @query('#ieds') iedToggle?: IconButtonToggle;

  @query('#about') about?: Dialog;

  @query('#iedMenu') iedMenu?: Menu;

  @query('sld-editor') sldEditor?: SldEditor;

  zoomIn() {
    this.gridSize += 3;
  }

  zoomOut() {
    this.gridSize -= 3;
    if (this.gridSize < 2) this.gridSize = 2;
  }

  startPlacing(element: Element | undefined) {
    this.reset();
    this.sldEditor?.startPlacing(element);
  }

  reset() {
    this.inAction = false;
    this.sldEditor?.resetWithOffset();
  }

  handleKeydown = ({ key }: KeyboardEvent) => {
    if (key === 'Escape') this.reset();
  };

  connectedCallback() {
    super.connectedCallback();
    window.addEventListener('keydown', this.handleKeydown);
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    window.removeEventListener('keydown', this.handleKeydown);
  }

  updated(changedProperties: Map<string, any>) {
    if (this.iedMenu)
      this.iedMenu.anchor = this.iedMenu.previousElementSibling as HTMLElement;
    if (!changedProperties.has('doc')) return;
    const sldNsPrefix = this.doc.documentElement.lookupPrefix(sldNs);
    if (sldNsPrefix) this.nsp = sldNsPrefix;
    else
      this.doc.documentElement.setAttributeNS(
        xmlnsNs,
        `xmlns:${this.nsp}`,
        sldNs
      );

    [
      'Substation',
      'VoltageLevel',
      'Bay',
      'ConductingEquipment',
      'PowerTransformer',
      'TransformerWinding',
    ].forEach(tag => {
      this.templateElements[tag] = this.doc.createElementNS(
        this.doc.documentElement.namespaceURI,
        tag
      );
    });
    this.templateElements.BusBar = makeBusBar(this.doc, this.nsp);
  }

  convertSldAttributes() {
    const convertEdits = convertSldLayout(this.doc, this.nsp);
    this.dispatchEvent(newEditEventV2(convertEdits));
  }

  render() {
    if (!this.doc) return html`<p>Please open an SCL document</p>`;
    if (hasOldNamespace(this.doc))
      return html`<mwc-button @click="${() => this.convertSldAttributes()}"
        >Convert SLD Layout</mwc-button
      >`;

    const ieds = Array.from(this.doc.querySelectorAll(':root > IED'));
    const iedRefs = Array.from(
      this.doc.querySelectorAll(':root > Substation')
    ).flatMap(sub => iedReferences(sub));

    const refForIed = (ied: Element) =>
      iedRefs.find(ref => ref.getAttributeNS(sldNs, 'id') === identity(ied));

    const unusedIeds = ieds.filter(ied => !refForIed(ied));

    const unusedIedRefs = iedRefs.filter(iedRef => !resolveIed(iedRef));

    const usedIedRefs = Array.from(ieds)
      .sort((a, b) => {
        const aName = a.getAttribute('name') ?? '';
        const bName = b.getAttribute('name') ?? '';

        const aRef = refForIed(a);
        const aIsUsed = !!aRef && !!getSLDAttributes(aRef, 'x');

        const bRef = refForIed(b);
        const bIsUsed = !!bRef && !!getSLDAttributes(bRef, 'x');

        if (aIsUsed !== bIsUsed) return aIsUsed ? -1 : 1;

        return aName.localeCompare(bName, undefined, {
          sensitivity: 'base',
        });
      })
      .filter(ied => !!getSLDAttributes(refForIed(ied) ?? ied, 'x'));

    return html`<main>
      <nav>
        ${
          Array.from(
            this.doc.querySelectorAll(':root > Substation > VoltageLevel > Bay')
          ).find(bay => !isBusBar(bay))
            ? eqTypes
                .map(
                  eqType => html`<mwc-fab
                    mini
                    label="Add ${eqType}"
                    title="Add ${eqType}"
                    @click=${() => {
                      const element =
                        this.templateElements.ConductingEquipment!.cloneNode() as Element;
                      element.setAttribute('type', eqType);
                      this.startPlacing(element);
                    }}
                    >${equipmentIcon(eqType)}</mwc-fab
                  >`
                )
                .concat()
            : nothing
        }${
      this.doc.querySelector(':root > Substation > VoltageLevel')
        ? html`<mwc-fab
              mini
              icon="horizontal_rule"
              @click=${() => {
                const element = this.templateElements.BusBar!.cloneNode(
                  true
                ) as Element;
                this.startPlacing(element);
              }}
              label="Add Bus Bar"
              title="Add Bus Bar"
            >
            </mwc-fab
            ><mwc-fab
              mini
              label="Add Bay"
              title="Add Bay"
              @click=${() => {
                const element =
                  this.templateElements.Bay!.cloneNode() as Element;
                this.startPlacing(element);
              }}
              style="--mdc-theme-secondary: #12579B; --mdc-theme-on-secondary: white;"
            >
              ${bayIcon}
            </mwc-fab>`
        : nothing
    }${
      Array.from(this.doc.documentElement.children).find(
        c => c.tagName === 'Substation'
      )
        ? html`<mwc-fab
              mini
              label="Add VoltageLevel"
              title="Add VoltageLevel"
              @click=${() => {
                const element =
                  this.templateElements.VoltageLevel!.cloneNode() as Element;
                this.startPlacing(element);
              }}
              style="--mdc-theme-secondary: #F5E214;"
            >
              ${voltageLevelIcon}
            </mwc-fab>
            ${ieds.length > 0 || unusedIeds.length > 0
              ? html`<mwc-fab
                    mini
                    icon="developer_board"
                    label="Add IED"
                    title="Add IED"
                    @click=${() => {
                      if (this.iedToggle) this.iedToggle.on = true;
                      this.iedMenu?.show();
                    }}
                  ></mwc-fab>
                  <mwc-menu
                    fixed
                    corner="BOTTOM_RIGHT"
                    menuCorner="END"
                    id="iedMenu"
                    @selected=${(ev: SingleSelectedEvent) => {
                      const selectedListItem = (ev.target as List)
                        .selected! as ListItem;
                      if (!selectedListItem) return;

                      const name = selectedListItem.dataset.name!;
                      selectedListItem.selected = false;

                      if (name === 'Delete Unmatched') {
                        const edits: EditV2[] = [];
                        iedRefs
                          .filter(referencedIed => !resolveIed(referencedIed))
                          .forEach(unusedReferencedIed => {
                            const parent = unusedReferencedIed.parentElement;
                            if (
                              parent?.tagName === 'Private' &&
                              parent.getAttribute('type') ===
                                'OpenSCD-SLD-Layout' &&
                              parent.childElementCount === 1
                            )
                              edits.push({ node: parent });
                            else edits.push({ node: unusedReferencedIed });
                          });

                        this.dispatchEvent(newEditEventV2(edits));
                      } else {
                        const ied = ieds.find(
                          item => item.getAttribute('name') === name
                        );
                        if (!ied) return;

                        const element = this.insertOrGetIed(ied, this.doc);
                        this.iedMenu?.close();
                        this.startPlacing(element);
                      }
                    }}
                  >
                    <mwc-list>
                      ${unusedIedRefs.length > 0
                        ? html`<mwc-list-item
                            style="--mdc-themes-text-primary-on-background: #BB1326; --mdc-theme-text-icon-on-background: #BB1326;"
                            graphic="control"
                            hasMeta
                            data-name="Delete Unmatched"
                          >
                            <span
                              >Remove reference to ${unusedIedRefs.length}
                              missing IED${unusedIedRefs.length > 1 ? 's' : ''}
                              from the SLD</span
                            >
                            <mwc-icon slot="graphic">delete</mwc-icon>
                          </mwc-list-item>`
                        : nothing}
                      ${unusedIeds.length > 0
                        ? html`<mwc-list-item noninteractive>
                              <span><strong>Available IEDs</strong></span>
                            </mwc-list-item>
                            ${unusedIeds.map(
                              ied => html` <mwc-list-item
                                twoline
                                data-name="${ied.getAttribute('name')!}"
                              >
                                <span>${ied.getAttribute('name')!}</span>
                                <span slot="secondary">
                                  ${[
                                    ied.getAttribute('manufacturer'),
                                    ied.getAttribute('type'),
                                    ied.getAttribute('desc'),
                                  ]
                                    .filter(a => !!a)
                                    .join(' - ')}
                                </span>
                              </mwc-list-item>`
                            )}`
                        : nothing}
                      ${usedIedRefs.length > 0
                        ? html`<mwc-list-item noninteractive>
                              <span><strong>Used IEDs</strong></span>
                            </mwc-list-item>
                            ${usedIedRefs.map(
                              ied => html`<mwc-list-item
                                twoline
                                hasMeta
                                data-name="${ied.getAttribute('name')!}"
                              >
                                <span>${ied.getAttribute('name')!}</span>
                                <span slot="secondary">
                                  ${[
                                    ied.getAttribute('manufacturer'),
                                    ied.getAttribute('type'),
                                    ied.getAttribute('desc'),
                                  ]
                                    .filter(a => !!a)
                                    .join(' - ')}
                                </span>
                                <mwc-icon slot="meta">pin_drop</mwc-icon>
                              </mwc-list-item>`
                            )}`
                        : nothing}
                    </mwc-list>
                  </mwc-menu>`
              : nothing}`
        : nothing
    }<mwc-fab
          mini
          icon="margin"
          @click=${() => this.insertSubstation()}
          label="Add Substation"
          style="--mdc-theme-secondary: #BB1326; --mdc-theme-on-secondary: white;"
          title="Add Substation"
        >
        </mwc-fab
        >${
          Array.from(this.doc.documentElement.children).find(
            c => c.tagName === 'Substation'
          )
            ? html`<mwc-fab
                  mini
                  label="Add Single Winding Auto Transformer"
                  title="Add Single Winding Auto Transformer"
                  @click=${() => {
                    const element =
                      this.templateElements.PowerTransformer!.cloneNode() as Element;
                    element.setAttribute('type', 'PTR');
                    setSLDAttributes(element, this.nsp, {
                      kind: 'auto',
                      rot: '3',
                    });
                    const winding =
                      this.templateElements.TransformerWinding!.cloneNode() as Element;
                    winding.setAttribute('type', 'PTW');
                    winding.setAttribute('name', 'W1');
                    element.appendChild(winding);
                    this.startPlacing(element);
                  }}
                  >${ptrIcon(1, { kind: 'auto' })}</mwc-fab
                ><mwc-fab
                  mini
                  label="Add Two Winding Auto Transformer"
                  title="Add Two Winding Auto Transformer"
                  @click=${() => {
                    const element =
                      this.templateElements.PowerTransformer!.cloneNode() as Element;
                    element.setAttribute('type', 'PTR');
                    setSLDAttributes(element, this.nsp, { kind: 'auto' });
                    const windings = [];
                    for (let i = 1; i <= 2; i += 1) {
                      const winding =
                        this.templateElements.TransformerWinding!.cloneNode() as Element;
                      winding.setAttribute('type', 'PTW');
                      winding.setAttribute('name', `W${i}`);
                      windings.push(winding);
                    }
                    element.append(...windings);
                    this.startPlacing(element);
                  }}
                  >${ptrIcon(2, { kind: 'auto' })}</mwc-fab
                ><mwc-fab
                  mini
                  label="Add Two Winding Transformer"
                  title="Add Two Winding Transformer"
                  @click=${() => {
                    const element =
                      this.templateElements.PowerTransformer!.cloneNode() as Element;
                    element.setAttribute('type', 'PTR');
                    const windings = [];
                    for (let i = 1; i <= 2; i += 1) {
                      const winding =
                        this.templateElements.TransformerWinding!.cloneNode() as Element;
                      winding.setAttribute('type', 'PTW');
                      winding.setAttribute('name', `W${i}`);
                      windings.push(winding);
                    }
                    element.append(...windings);
                    this.startPlacing(element);
                  }}
                  >${ptrIcon(2)}</mwc-fab
                ><mwc-fab
                  mini
                  label="Add Three Winding Transformer"
                  title="Add Three Winding Transformer"
                  @click=${() => {
                    const element =
                      this.templateElements.PowerTransformer!.cloneNode() as Element;
                    element.setAttribute('type', 'PTR');
                    const windings = [];
                    for (let i = 1; i <= 3; i += 1) {
                      const winding =
                        this.templateElements.TransformerWinding!.cloneNode() as Element;
                      winding.setAttribute('type', 'PTW');
                      winding.setAttribute('name', `W${i}`);
                      windings.push(winding);
                    }
                    element.append(...windings);
                    this.startPlacing(element);
                  }}
                  >${ptrIcon(3)}</mwc-fab
                ><mwc-fab
                  mini
                  label="Add Single Winding Earthing Transformer"
                  title="Add Single Winding Earthing Transformer"
                  @click=${() => {
                    const element =
                      this.templateElements.PowerTransformer!.cloneNode() as Element;
                    element.setAttribute('type', 'PTR');
                    setSLDAttributes(element, this.nsp, { kind: 'earthing' });
                    const winding =
                      this.templateElements.TransformerWinding!.cloneNode() as Element;
                    winding.setAttribute('type', 'PTW');
                    winding.setAttribute('name', 'W1');
                    element.appendChild(winding);
                    this.startPlacing(element);
                  }}
                  >${ptrIcon(1, { kind: 'earthing' })}</mwc-fab
                ><mwc-fab
                  mini
                  label="Add Two Winding Earthing Transformer"
                  title="Add Two Winding Earthing Transformer"
                  @click=${() => {
                    const element =
                      this.templateElements.PowerTransformer!.cloneNode() as Element;
                    element.setAttribute('type', 'PTR');
                    setSLDAttributes(element, this.nsp, { kind: 'earthing' });
                    const windings = [];
                    for (let i = 1; i <= 2; i += 1) {
                      const winding =
                        this.templateElements.TransformerWinding!.cloneNode() as Element;
                      winding.setAttribute('type', 'PTW');
                      winding.setAttribute('name', `W${i}`);
                      windings.push(winding);
                    }
                    element.append(...windings);
                    this.startPlacing(element);
                  }}
                  >${ptrIcon(2, { kind: 'earthing' })}</mwc-fab
                >`
            : nothing
        }${
      this.doc.querySelector('VoltageLevel, PowerTransformer')
        ? html`<mwc-icon-button-toggle
            id="labels"
            label="Toggle Labels"
            title="Toggle Labels"
            on
            onIcon="font_download"
            offIcon="font_download_off"
            @click=${() => this.requestUpdate()}
          ></mwc-icon-button-toggle>`
        : nothing
    }${
      (ieds.length > 0 || unusedIeds.length > 0) &&
      this.doc.querySelector(':root > Substation')
        ? html`<mwc-icon-button-toggle
            id="ieds"
            label="Toggle IEDs"
            title="Toggle IEDs"
            on
            onIcon="developer_board"
            offIcon="developer_board_off"
            @click=${() => {
              if (this.iedMenu) this.requestUpdate();
            }}
          ></mwc-icon-button-toggle>`
        : nothing
    }${
      this.doc.querySelector('Substation')
        ? html`<mwc-icon-button
              icon="zoom_in"
              label="Zoom In"
              title="Zoom In (${Math.round((100 * (this.gridSize + 3)) / 32)}%)"
              @click=${() => this.zoomIn()}
            >
            </mwc-icon-button
            ><mwc-icon-button
              icon="zoom_out"
              label="Zoom Out"
              ?disabled=${this.gridSize < 4}
              title="Zoom Out (${Math.round(
                (100 * (this.gridSize - 3)) / 32
              )}%)"
              @click=${() => this.zoomOut()}
            ></mwc-icon-button>`
        : nothing
    }
        </mwc-icon-button
        >${
          this.inAction
            ? html`<mwc-icon-button
                icon="close"
                label="Cancel"
                title="Cancel"
                @click=${() => this.reset()}
              ></mwc-icon-button>`
            : html`<mwc-icon-button
                icon="info"
                label="About"
                title="About"
                @click=${() => this.about?.show()}
              ></mwc-icon-button>`
        }
      </nav>
      <sld-editor 
        .doc="${this.doc}"
        .docVersion=${this.docVersion}
        .gridSize=${this.gridSize}
        .showLabels=${this.showLabels}
        .showIeds=${this.showIeds}
        @sld-editor-in-action=${({ detail }: CustomEvent) => {
          this.inAction = detail;
        }}
      >
      </sld-editor>
    </main>
    ${staticHtml`<mwc-dialog id="about" heading="About">
        <div>${unsafeStatic(aboutContent)}</div>
        <mwc-button dialogAction="close" slot="primaryAction">
          close
        </mwc-button>
      </mwc-dialog>`}`;
  }

  insertOrGetIed(ied: Element, doc: XMLDocument): Element {
    const referencedIed = iedReferences(doc).find(
      ref => ref.getAttributeNS(sldNs, 'id') === identity(ied)
    );

    if (referencedIed) return referencedIed;

    const newIedReference = doc.createElementNS(sldNs, `${this.nsp}:Reference`);
    newIedReference.setAttributeNS(
      sldNs,
      `${this.nsp}:id`,
      String(identity(ied))
    );
    newIedReference.setAttributeNS(sldNs, `${this.nsp}:type`, 'IED');

    return newIedReference;
  }

  insertSubstation() {
    const parent = this.doc.documentElement;
    const node = this.doc.createElementNS(
      this.doc.documentElement.namespaceURI,
      'Substation'
    );
    const reference = getReference(parent, 'Substation');
    let index = 1;
    while (this.doc.querySelector(`:root > Substation[name="S${index}"]`))
      index += 1;
    node.setAttribute('name', `S${index}`);
    setSLDAttributes(node, this.nsp, { w: '50', h: '25' });
    this.dispatchEvent(newEditEventV2({ parent, node, reference }));
  }

  static styles = css`
    main {
      padding: 16px;
      width: fit-content;
    }

    div {
      margin-top: 12px;
    }

    nav {
      user-select: none;
      position: sticky;
      top: 68px;
      left: 16px;
      width: fit-content;
      max-width: calc(100vw - 32px);
      background: #fffd;
      border-radius: 24px;
      z-index: 1;
    }

    mwc-icon-button,
    mwc-icon-button-toggle {
      --mdc-theme-text-disabled-on-light: #aaa;
      color: rgb(0, 0, 0 / 0.83);
    }
    mwc-fab {
      --mdc-theme-secondary: #fff;
      --mdc-theme-on-secondary: rgb(0, 0, 0 / 0.83);
    }
  `;
}
